export const calcMu = (w:number, sh:number) => {
  const r = +(w * 1.09).toFixed(2), tax = +(r * 0.0825).toFixed(2);
  return { r, sh, tax, tot: +((r + sh + tax + 0.3) / 0.971).toFixed(2) };
};
